/**
 * @file ornate-popup.ts
 * @copyright 2026, Firaxis Games
 * @description A Popup that has is styled to be more ornate then the usual popup
 */

import { Component, For, mergeProps, ParentComponent, Show, type JSX } from "solid-js";

import { Button, ButtonProps } from "#core/ui-next/components/button.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

interface OrnatePopupProps extends JSX.HTMLAttributes<HTMLDivElement> {
	class?: string;
	headerIcon?: string;
	buttons?: ButtonProps[];
	topIconClass?: string;
	topIconSrc?: string;
	topIconBackgroundTint?: string;
	closePopupCallback?: () => void;
	noClose?: boolean;
	longFiligree?: boolean;
	isFullscreen?: boolean;
}

interface OrnateTopIconProps extends JSX.HTMLAttributes<HTMLDivElement> {
	backgroundTint: string;
	iconSrc: string;
	iconClass?: string;
}

export const OrnateTopIcon: Component<OrnateTopIconProps> = (props) => {
	return (
		<div
			{...props}
			class={`flex justify-center items-center size-16 relative ${props.class}`}
		>
			<div
				class="inset-2 bg-contain bg-no-repeat bg-center absolute"
				style={{
					"background-image": "url(blp:subsystem_panel_header_icon_backing)",
					// eslint-disable-next-line solid/style-prop
					"fxs-background-image-tint": props.backgroundTint,
				}}
			/>
			<div
				class="inset-0 bg-contain bg-no-repeat bg-center absolute flex justify-center items-center"
				style={{
					"background-image": "url(blp:pedia_circle_frame)",
				}}
			>
				<Icon
					class={`${props.iconClass}`}
					name={props.iconSrc}
				/>
			</div>
		</div>
	);
};

const OrnatePopupComponent: ParentComponent<OrnatePopupProps> = (props) => {
	const mergedProps = mergeProps({ class: "", topIconClass: "absolute size-16 -mt-1", buttons: [] }, props);
	return (
		<div
			class={`${props.isFullscreen ? "px-6 size-full" : "img-unit-panelbox frame-top-curve px-12"} relative flex flex-col items-center ${mergedProps.class}`}
		>
			<Show when={props.isFullscreen}>
				<div class="fixed inset-0 img-unit-panelbox pointer-events-none" />
			</Show>
			<Show when={!props.isFullscreen}>
				<div class="flex flex-row min-w-96 -mt-4 justify-center relative">
					<Show
						when={props.longFiligree}
						fallback={
							<>
								<div class="filigree-panel-top-left" />
								<div class="filigree-panel-top-right" />
							</>
						}
					>
						<div class="filigree-panel-top-long" />
					</Show>
					<Show when={mergedProps.topIconSrc}>
						<OrnateTopIcon
							class="absolute -top-5"
							backgroundTint={mergedProps.topIconBackgroundTint || ""}
							iconClass={mergedProps.topIconClass}
							iconSrc={mergedProps.topIconSrc || ""}
						/>
					</Show>
				</div>
			</Show>
			{mergedProps.children}
			<Show when={!props.noClose}>
				<CloseButton
					class={`absolute ${props.isFullscreen ? "top-3 right-3" : "top-0 right-0 size-12"} cursor-pointer group`}
					onActivate={mergedProps.closePopupCallback}
				/>
			</Show>
			<Show when={mergedProps.buttons.length > 0}>
				<div class="my-4">
					<For each={mergedProps.buttons}>
						{(button) => (
							<Button
								class="mx-4"
								onActivate={button.onActivate}
							>
								<L10n.Compose text={button.name || ""} />
							</Button>
						)}
					</For>
				</div>
			</Show>
		</div>
	);
};

export const OrnatePopupFrame = ComponentRegistry.register({
	name: "OrnatePopupFrameComponent",
	createInstance: OrnatePopupComponent,
});
